"""Export a CPU test lock from existing locks, without resolving or downloading.

Recipe package versions and artifact hashes come from the Edge lock. Only Torch
and TorchVision use the matching CPU wheels already pinned by Stage-1 CI. These
tests use explicit release API doubles and do not establish release compatibility.
"""

import argparse
import json
import re
import tomllib
from pathlib import Path
from urllib.parse import unquote

ROOT = Path(__file__).resolve().parents[2]
DESTINATION = ROOT / ".github/requirements/pylock.alpamayo2edge-cpu.toml"
TEST_ROOTS = (
    "accelerate",
    "colorlog",
    "einops",
    "hydra-core",
    "numpy",
    "pandas",
    "physical-ai-av",
    "pyarrow",
    "pytest",
    "safetensors",
    "scipy",
    "torch",
    "torchvision",
    "transformers",
    "wandb",
)


def linux_python312_wheel(url: str) -> bool:
    filename = unquote(url.rsplit("/", 1)[-1])
    python_tag, abi, platform = filename.removesuffix(".whl").rsplit("-", 3)[-3:]
    if platform != "any" and not ("manylinux" in platform and "x86_64" in platform):
        return False
    if python_tag in {"py3", "py2.py3", "cp312"}:
        return True
    version = re.fullmatch(r"cp3(\d+)", python_tag)
    return abi == "abi3" and version is not None and int(version[1]) <= 12


def export_lock() -> str:
    recipe = tomllib.loads((ROOT / "recipes/alpamayo2edge_sft/uv.lock").read_text())
    cpu = tomllib.loads(
        (ROOT / ".github/requirements/pylock.stage1-vlm-cpu.toml").read_text()
    )
    packages = {package["name"]: package for package in recipe["package"]}
    cpu_packages = {package["name"]: package for package in cpu["packages"]}
    selected = set()

    def visit(name: str) -> None:
        if name in selected or name.startswith("nvidia-") or name == "triton":
            return
        selected.add(name)
        for dependency in packages[name].get("dependencies", []):
            visit(dependency["name"])

    for name in TEST_ROOTS:
        visit(name)
    lines = [
        "# Generated by python .github/scripts/export_edge_cpu_lock.py; do not edit.",
        "# CPU behavior tests with release API doubles, not public-release integration.",
        'lock-version = "1.0"',
        'created-by = "export_edge_cpu_lock.py"',
        'requires-python = "==3.12.*"',
    ]
    for name in sorted(selected):
        package = packages[name]
        if name in {"torch", "torchvision"}:
            package = cpu_packages[name]
            if package["version"] != packages[name]["version"] + "+cpu":
                raise ValueError(f"CPU wheel and recipe versions differ for {name}")
        lines.extend(
            [
                "",
                "[[packages]]",
                f"name = {json.dumps(name)}",
                f"version = {json.dumps(package['version'])}",
            ]
        )
        artifacts = [
            wheel
            for wheel in package.get("wheels", [])
            if linux_python312_wheel(wheel["url"])
        ]
        field = "wheels"
        if not artifacts:
            if name != "antlr4-python3-runtime":
                raise ValueError(f"No Python 3.12 Linux wheel for {name}")
            artifacts, field = [package["sdist"]], "sdist"
        entries = []
        for artifact in artifacts:
            digest = (
                artifact["hashes"]["sha256"]
                if "hashes" in artifact
                else artifact["hash"].removeprefix("sha256:")
            )
            entries.append(
                f"{{ url = {json.dumps(artifact['url'])}, "
                f"hashes = {{ sha256 = {json.dumps(digest)} }} }}"
            )
        value = "[" + ", ".join(entries) + "]" if field == "wheels" else entries[0]
        lines.append(f"{field} = {value}")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="Fail if the exported lock is stale"
    )
    args = parser.parse_args()
    generated = export_lock()
    if args.check:
        if not DESTINATION.is_file() or DESTINATION.read_text() != generated:
            raise SystemExit(
                "Edge CPU lock is stale; run python .github/scripts/export_edge_cpu_lock.py"
            )
    else:
        DESTINATION.write_text(generated)
